const renderMapPage = createMapPageHarness(MapPage);

const PP = '00000000-0000-4000-8000-000000000001'; const SW = '00000000-0000-4000-8000-000000000002'; const PC = '00000000-0000-4000-8000-000000000003'; const A = '00000000-0000-4000-8000-000000000010'; const B = '00000000-0000-4000-8000-000000000011';
const node = (id: string, label: string, attributes: Record<string, unknown> = {}) => ({ id: `node-${id}`, kind: 'PHYSICAL_OBJECT', label, source_refs: [{ ref_type: 'CANONICAL_FACT', entity_type: 'PhysicalObject', entity_id: id }], attributes });
const blueprintPresentation = (slots: Array<{ x: number; y: number }> = [{ x: .5, y: .5 }]) => ({ blueprint_presentation: { body: { kind: 'RECTANGLE', width: 100, height: 100 }, slots: slots.map((rendered_position) => ({ face: 'FRONT', rendered_position })) } });
const physical = (...ids: string[]): TopologyProjectionDocument => ({ schema_version: '1.0', layer: 'L1', detail_level: 'PHYSICAL_OBJECT', nodes: ids.map((id) => node(id, id === PP ? 'PP1' : id === SW ? 'SW1' : 'PC1')), edges: [], gaps: [], warnings: [] });
const logical: TopologyProjectionDocument = { schema_version: '1.0', layer: 'L2', detail_level: 'DEVICE', nodes: [node(PP, 'PP1'), node(PC, 'PC1')], edges: [], gaps: [], warnings: [] };
const scopedProjection = (request: any) => Promise.resolve(request.layer === 'L2' ? logical : physical(...request.scope.include_entities.map((ref: any) => ref.entity_id)));
const saved = (id: string, placements: Array<[string, number, number, number?, number?]>, cable_routes: any[] = [], regions: any[] = []) => ({ map_ref: { entity_type: 'SavedMap' as const, entity_id: id }, name: id === A ? 'A' : 'B', created_at: 'x', updated_at: 'x', placements: placements.map(([objectId, x, y, logicalX, logicalY]) => ({ physical_object_ref: { ref_type: 'CANONICAL_FACT', entity_type: 'PhysicalObject', entity_id: objectId }, positions: { 'L1/PHYSICAL_OBJECT': { x, y }, ...(logicalX === undefined || logicalY === undefined ? {} : { 'L2/DEVICE': { x: logicalX, y: logicalY } }) } })), cable_routes, regions });
const Location = () => <output data-testid="location">{useLocation().search}</output>;
const inventory = { schema_version: '1.0' as const, equipment: [{ physical_object_ref: { ref_type: 'CANONICAL_FACT' as const, entity_type: 'PhysicalObject', entity_id: SW }, label: 'SW17', class: 'switch', map_memberships: [] }, { physical_object_ref: { ref_type: 'CANONICAL_FACT' as const, entity_type: 'PhysicalObject', entity_id: PC }, label: 'Z2', map_memberships: [] }], cables: [{ cable_ref: { ref_type: 'CANONICAL_FACT' as const, entity_type: 'Cable', entity_id: 'cable' }, label: 'Cable', resolution: 'UNRESOLVED' as const, gaps: [], warnings: [] }], gaps: [], warnings: [] };
const renderPage = (source: TopologyDataSource, maps: SavedMapDataSource, entry = `/map?map=${A}&view=physical`, catalog = { loadCatalogInventory: vi.fn().mockResolvedValue(inventory) }) => renderMapPage({ dataSource: source, deviceDetailsDataSource: { loadDeviceDetails: vi.fn() }, savedMapDataSource: maps, catalogInventoryDataSource: catalog, physicalObjectDeleteDataSource: { deletePhysicalObject: vi.fn() } }, entry, <Location />);

